WFJ.Data.add("quest", {
  [88756] = { "派手な一発を取り戻す", "Dark Iron Dwarfの野営地からStolen Explosivesを$N1個取り戻す。", "Dark Ironsはここから東のDireforge Hillにいくつか野営地を構えとる。奴らはわしらの建設現場からexplosivesをごっそり盗んで、自分らのテントに運び込んだんだ。\n\nDark Ironsが火薬樽ひとつでどんな悪さをしでかすか、わざわざ言うまでもねえだろう！\n\nDark Ironsが危険なのは分かっとるが、あの樽は取り返さにゃならん。ほかの樽とは、赤い印がついとるから見分けがつく。Dark Ironsにくれてやるわけにはいかん！", "Dark Ironどもとの戦争は、延々と続くばかりだ！", "ああ、これで肩の荷が下りたぜ。少なくともDark Ironどもが爆弾車を俺たちの荷馬車に突っ込ませることはできなくなった……投石機で投げ込むことも……丘の上から転がり落とすことも……スライムに食わせてから、そのスライムを野営地の近くに放して火をつけることもな。\n\nあとは火薬が湿らんようにするだけだ！\n\nありがとよ！", 0xc57287cb, 0x0a061175, 0xf19bd9f0, 0x0d40ddf5, 0xce23de7c, "....." },
  [88757] = { "失われし者たちの装身具", "Essene's Necklace、Essene's Spellbook、Essene's Waterskinを持ち帰る。", "Dark Ironsから逃げている間に、装備をたくさん落としてしまった！\n\nどうやらなくしたのは……緑の革のwaterskinと、spellbookと、necklaceと……とにかく、どれも必要なものなんだ！\n\n私が荷物を詰め直して息を整えている間に見つけてくれたら、すごく助かる。", nil, nil, 0xb1b07501, 0x8dd0b2c0, 0xd5dd92b9, nil, nil, "...mm" },
  [88758] = { "失われし者たちの想い", "EsseneのメモをCorma Villardのもとへ持ち帰る。", "あとは荷物を詰め直すだけで、ここから出られる！\n\n最後にもうひとつ頼みを聞いてくれるなら、ほら、このメモをCormaに届けてくれ。私が生きていて、今そっちへ向かっていると伝わるはずだ！", nil, nil, 0x4c47fdf9, 0x12fd10da, 0x3d2951ce, nil, nil, "...mm" },
  [88807] = { "Spitelashの討伐", "AzsharaにいるCommander Truesongのために、Spitelash Warriorsを8体とSpitelash Screamersを8体倒してください。", "Azsharaは美しく見えるかもしれないが、呪われた地だ。その海の底深くには恐怖が潜み、浮上して世界を引き裂く時を待っている。\n\n今の我々にできるのは、すでに浮上してきた恐怖と戦うことだけだ。\n\nSpitelash Nagaが北東のRuins of Eldarathを占拠している。廃墟の中にいる者たちは守りが固いので、まずは周辺の弱い者たちから仕留めねばならない。\n\n見てのとおり、ここではもう一人戦い手が加わってくれればいつでも助かる。君にその覚悟があるならな。", nil, nil, 0x98f4f1f6, 0xf567af16, 0xc3e0fca0, nil, nil, "...mm" },
  [88809] = { "Eldarathの保全", "AzsharaにいるCommander Truesongのために、Spitelash Serpent Guards、Spitelash Sirens、Spitelash MyrmidonsからEldarath Relicsを$N1個、そしてLord Sarthiss' Headを集めてください。", "数千年前、Eldarathは目を見張るほどの場所だった。Kaldoreiの栄光と力を示す生きた証だったのだ。それに比べれば、今日我々がEldarathと呼んでいるものは、瓦礫の山とすら言えない。\n\nそれでも、残されたものには救い出す価値がある。我々の歴史を守るためだけだとしても。Eldarathが完全に荒らされる前に、Spitelashを追い出さねばならない。\n\n北東への道をたどれば、廃墟のまっただ中に出る。そこへ行き、我々の遺物をできるだけ多く取り戻してくれ。それから、奴らの指揮官の首もな。", nil, nil, 0x3265e3cf, 0xdeed3688, 0x0fbfead7, nil, nil, "...mm" },
  [88812] = { "Ravencrestの奪還", "AzsharaにいるCommander Truesongのために、Spitelash Battlemastersを5体とSpitelash Enchantressesを5体倒し、Ravencrest Monument付近にある3つのNaga Power Stonesを無力化してください。", "KaldoreiのRavencrest家のことも、やがて時が忘れてしまうのではないかと恐れている。崩れかけた記念碑がひとつ、ここに彼らがいたことを示す唯一の証として残っているだけだ。\n\nその記念碑は、南の半島の突端にある崖の上にある。そこにいるSpitelashの女魔術師たちは、魔法を導くための力の石を一揃い持っている。この護符を持って行き、それらを無力化してくれ。そうすればSpitelashの魔法は損なわれ、奴らを追い出す上で我々が優位に立てる。\n\nついでに、君自身の手でnagaを何体か仕留めておいてくれ。", nil, nil, 0x50486909, 0xe255d01f, 0xb035309c, nil, nil, "...mm" },
  [88813] = { "大蛇の頭", "Warlord Krellianの首をAzsharaにいるCommander Truesongのところへ持って行ってください。", "最後の標的はSpitelashの首領、Warlord Krellianだ。奴はEldarathの廃墟にあるTemple of Zin-Malorで、護衛の陰に隠れて怯えている。\n\nKrelianの首を斬り落とせば、手下どもは恐れをなして海へ這い戻っていくだろう。そうすれば、ついにAzsharaは再びKaldoreiのものとなる。", nil, nil, 0x44e98df6, 0xdc00b1b5, 0x90c557e5, nil, nil, "...mm" },
  [88821] = { "接触", "Shattered Strandで最後に目撃されたKaldoreiの女性を見つけてください。", "Shattered Strandの崖沿いを偵察していたとき、我々の歩哨の一人が浜辺にいるkaldoreiの女性に気づいた。\n\n明らかに彼女は我々の遠征隊の者ではないし、戦士らしい様子もなかった。それなら、こんな危険な場所で何をしているのだろうか。\n\nできれば、彼女と接触してみてほしい。ここにいる目的と、もしかすると我々と利害が一致するのかどうかを知りたい。\n\n最後に目撃されたのは東の海岸、Bay of Stormsの北側沿いだ。", nil, nil, 0x491d89a5, 0x1f0a2682, 0x188a9d50, nil, nil, "...mm" },
  [88857] = { "歩哨の救出", "Keldara SunbladeがHaldarr Encampmentから脱出するのを手助けし、Talrendis PointにいるCommander Truesongと話してください。", "<歩哨は低い声でささやく>\n\n聞いてくれ、{class}、奴らに聞かれる前に。私はTalrendis Pointの歩哨だ。ここのsatyrは私が怪我をしていると思っているが、ふりをしているだけだ。奴らが油断して、私が逃げ出せる瞬間を待っているのだ。\n\n君が来たのは、まさにその瞬間かもしれない。\n\nここから出るのを手伝ってくれないか？", nil, nil, 0x20e50750, 0x312c117d, 0x92d6a27d, nil, nil, "...mm" },
  [88884] = { "Highborneの石板", "Southridge Beachの遺跡の中からhighborneの石板を3枚見つけ、AzsharaにいるSaria Fairmoonのところへ持って行ってください。", "ここからすぐ南の浜辺沿いに、highborneの文字が刻まれた石板がいくつかある。秘術の法則と力についてのhighborneの研究を記録したものだ。\n\n石板は仏塔のような建物に保管されていて、nagaが見張っている。とても自分で手に入れようなんて気にはなれない。\n\n幸い、新しい助手が見つかったんだ！\n\nそれで、どうだい？知識の探求で、もう少し役に立ってくれないか？", nil, nil, 0x1c667b66, 0x7646c407, 0xac9c0bb0, nil, nil, "...mm" },
  [88917] = { "這い回る略奪者", "Ruins of Eldarathの中からStaff of Archmage Selwynを見つけ、AzsharaにいるSaria Fairmoonのところへ持って行ってください。", "私はhighborneの遺物を探しにここへ来た。一種の考古学者とでも呼んでくれ。\n\n西にあるEldarathの廃墟には遺物がたくさんあるが、今この瞬間にもnagaが廃墟を荒らしている。\n\nLady Sesspiraというnagaがその略奪を率いている。間違いなく、最高の発見物は自分のものにしているはずだ。\n\n私の研究が正しければ、彼女は堕ちたhighborneのメイジ、Archmage Selwynのstaffを持っているかもしれない。\n\nそのstaffを手に入れるのに力を貸してほしい、{race}。私のような学者は戦いには向いていないんだ。", nil, nil, 0x09007138, 0x5bdffc14, 0x14d00c3a, nil, nil, "...mm" },
})
